"""Rebuild original stage illustrations without changing the 500-question bank.

The complete, edition-labelled rules remain in classifications.json. This script
adds anatomy, distinct findings, and a short explanation of the decisive border.
All drawings are original vectors; no guideline figures are reproduced.
"""
import json
import re
from pathlib import Path

import clinical_art as a
from clinical_art import L

ROOT = Path(__file__).resolve().parents[1]


def labels(items):
    return [dict(id=id, text=value, number=index+1) for index, (id, value) in enumerate(items)]


ORIENT = {
 'kidney': L('Koronarschnitt der Niere. Rechts: schematische Beziehung der Nierenvene zur V. cava und zum Zwerchfell; keine maßstäbliche OP-Ansicht.', 'Coronal kidney section. Right: schematic renal vein, cava and diaphragm relationship; not a to-scale surgical view.', 'Corte renal coronal. Derecha: relación esquemática de vena renal, cava y diafragma; no es una vista quirúrgica a escala.'),
 'bladder': L('Links: koronare Blasenwand mit Trigonum und Blasenhals. Rechts: vergrößerter Wandschnitt vom Lumen zum äußeren Fett.', 'Left: coronal bladder wall, trigone and neck. Right: enlarged wall from lumen to external fat.', 'Izquierda: pared vesical coronal, trígono y cuello. Derecha: pared ampliada desde la luz hasta la grasa externa.'),
 'prostate': L('Vereinfachter männlicher Sagittalschnitt: Blase oben, Prostata darunter, Samenblase und Rektum posterior. cT und pT werden getrennt beurteilt.', 'Simplified male sagittal section: bladder above, prostate below, seminal vesicle and rectum posteriorly. cT and pT are assessed separately.', 'Corte sagital masculino simplificado: vejiga arriba, próstata abajo, vesícula seminal y recto posteriores. cT y pT se evalúan por separado.'),
 'testis': L('Schnitt durch Hoden und Hüllen: Parenchym → Albuginea → Vaginalis → Skrotalwand. Nebenhoden und Samenstrang sind getrennte Ausbreitungswege.', 'Testis and coverings: parenchyma → albuginea → vaginalis → scrotal wall. Epididymis and spermatic cord are separate routes of spread.', 'Testículo y cubiertas: parénquima → albugínea → vaginal → pared escrotal. Epidídimo y cordón son vías de extensión distintas.'),
 'penis': L('Längsschnitt mit dorsalem Cavernosum und ventralem Spongiosum; rechts unten ein axialer Schnitt mit zwei Cavernosa und der Urethra im Spongiosum.', 'Longitudinal section: dorsal cavernosum, ventral spongiosum. Lower right: axial section with paired cavernosa and urethra inside spongiosum.', 'Corte longitudinal: cavernoso dorsal y esponjoso ventral. Abajo a la derecha: corte axial con dos cavernosos y uretra dentro del esponjoso.'),
 'ureter': L('Links: längs eröffneter Ureter. Rechts: vergrößerter Wandschnitt. Bei Trauma sind Wandumfang, Kontinuität und Devaskularisation getrennte Befunde.', 'Left: longitudinal ureter. Right: enlarged wall. In trauma, wall circumference, continuity and devascularisation are separate findings.', 'Izquierda: uréter longitudinal. Derecha: pared ampliada. En trauma se distinguen circunferencia, continuidad y desvascularización.'),
 'adrenal': L('Vergrößerte Nebenniere über der Niere, mit Rinde, Mark, Kapsel und Vene. Das sympathische Paraganglion ist ein eigenständiger extraadrenaler Befund.', 'Enlarged adrenal above the kidney, with cortex, medulla, capsule and vein. A sympathetic paraganglion is a separate extra-adrenal site.', 'Suprarrenal ampliada sobre el riñón, con corteza, médula, cápsula y vena. El paraganglio simpático es una localización extraadrenal distinta.'),
 'urethra': L('Vereinfachter männlicher Sagittalschnitt. Prostatische und membranöse Urethra sind posterior; bulbäre und penile Urethra anterior. Die Klinik ergänzt das Bild.', 'Simplified male sagittal section. Prostatic and membranous urethra are posterior; bulbar and penile urethra anterior. Clinical assessment complements the drawing.', 'Corte sagital masculino simplificado. Uretra prostática y membranosa posteriores; bulbar y peneana anteriores. La valoración clínica complementa el dibujo.'),
 'bladder-trauma': L('Vereinfachter Sagittalschnitt der Blase. Grün gestrichelt: Peritonealumschlag über der Kuppel. Darm liegt intraperitoneal; Raum vor und neben der Blase extraperitoneal.', 'Simplified sagittal bladder section. Green dashed line: peritoneal reflection over the dome. Bowel lies intraperitoneally; the space anterior and lateral to bladder is extraperitoneal.', 'Corte sagital vesical simplificado. Línea verde discontinua: reflexión peritoneal sobre cúpula. Intestino intraperitoneal; espacio anterior y lateral a vejiga extraperitoneal.'),
 'spread': L('Schematische Körperkarte: rot markiert nur die ausgewählte Befallskategorie. Größe, Anzahl, Seite und Kapseldurchbruch werden nach der organabhängigen Regel beurteilt.', 'Schematic body map: red indicates the selected disease category. Size, number, side and extranodal extension follow the organ-specific rule.', 'Mapa corporal esquemático: rojo indica la categoría seleccionada. Tamaño, número, lateralidad y extensión extranodal siguen la regla del órgano.'),
 'markers': L('Drei unabhängige Markerachsen. Die höchste erfüllte Kategorie zählt; für S1 müssen alle drei Marker unter den S2-Grenzen liegen. Werte und Abnahmezeitpunkt gehören zum Befund.', 'Three independent marker axes. The highest fulfilled category counts; S1 requires all three markers below S2 thresholds. Values and sampling time belong in the assessment.', 'Tres ejes de marcadores independientes. Cuenta la categoría más alta; S1 exige los tres por debajo de S2. Se deben valorar cifras y momento de extracción.'),
}
MODELS={'bladder-trauma':(a.bladder_trauma,a.BLADDER_TRAUMA_LABELS),'kidney':(a.kidney,a.KIDNEY_LABELS),'bladder':(a.bladder,a.BLADDER_LABELS),'prostate':(a.prostate,a.PROSTATE_LABELS),'testis':(a.testis,a.TESTIS_LABELS),'penis':(a.penis,a.PENIS_LABELS),'ureter':(a.ureter,a.URETER_LABELS),'adrenal':(a.adrenal,a.ADRENAL_LABELS),'urethra':(a.urethra,a.URETHRA_LABELS)}


def build():
    file=ROOT/'data/classifications.json'; data=json.loads(file.read_text())
    guides={g['id']:g for g in data['guides']}
    ref_file=ROOT/'data/refs-classifications.json';refs=json.loads(ref_file.read_text())
    node_ref='classification-urethral-nodes'
    if not any(r['id']==node_ref for r in refs):
        refs.append(dict(id=node_ref,title='EAU 2026: Primary urethral carcinoma — diagnostic staging and regional lymph nodes',url='https://uroweb.org/guidelines/primary-urethral-carcinoma/chapter/diagnostic-evaluation-and-staging',checked='2026-10-12',scope='Site-specific inguinal and pelvic lymphatic drainage'))
        ref_file.write_text(json.dumps(refs,ensure_ascii=False,indent=2)+'\n')
    if node_ref not in guides['urethral']['references']:guides['urethral']['references'].append(node_ref)

    current=None

    def begin(id, model):
        nonlocal current
        current=guides[id]
        fn, labs=MODELS[model]
        current['visual']=dict(viewBox='0 0 960 640', anatomy=fn(), labels=labels(labs), orientation=ORIENT[model], stages=[])

    def stage(id, code, model, variant, boundary, name=None, row=None, section=None, cases=(), dimension='T', site=None):
        candidates=[r for si,s in enumerate(current['sections']) if section is None or si==section for r in s['rows'] if r['code']==(row or code)]
        assert candidates, (current['id'],code,row)
        if model=='spread': svg=a.spread(current['id'],variant,site); labs=list(a.SPREAD_LABELS)
        if model=='spread' and (current['id']=='penile' or site=='anterior'):
            labs.append(('pelvic-nodes',L('Pelvine Lymphknoten','Pelvic lymph nodes','Ganglios pélvicos')))
        if model=='spread' and site:
            station=L('Hiläre / retroperitoneale Knoten','Hilar / retroperitoneal nodes','Ganglios hiliares / retroperitoneales') if site=='proximal' else L('Inguinale Lymphknoten','Inguinal lymph nodes','Ganglios inguinales') if site=='anterior' else L('Pelvine Lymphknoten','Pelvic lymph nodes','Ganglios pélvicos')
            labs=[(id,station if id=='regional-nodes' else value) for id,value in labs]
        if model=='markers': svg=a.markers(variant); labs=[]
        elif model!='spread': fn,labs=MODELS[model];svg=fn(variant)
        if current['id']=='bladder' and code in ('T4a','T4b'):
            labs=labs+[(('adjacent-prostate',L('Prostatastroma (P)','Prostatic stroma (P)','Estroma prostático (P)')) if code=='T4a' else ('pelvic-wall',L('Beckenwand','Pelvic wall','Pared pélvica')))]
        current['visual']['stages'].append(dict(id=id,code=code,dimension=dimension,title=name or dict.fromkeys(('de','en','es'),code),svg=svg,labels=labels(labs),orientation=ORIENT[model],explanation=candidates[0]['description'],boundary=boundary,cases=[f'staging-trauma-{i:02}' for i in cases]))

    def spread_stages():
        # Exact organ-specific rules remain visible beside the illustrative map.
        for si,s in enumerate(current['sections']):
            if not any(s['title']['en'].startswith(p) for p in ('N:', 'cN:', 'pN:', 'cN / pN:', 'M:')):continue
            for r in s['rows']:
                code=r['code']
                if 'X' in code or code in ('N0','pN0','M0'):continue
                id=code.lower().replace(' / ','-').replace(' ','-')
                dim='M' if code.startswith('M') else 'pN' if code.startswith('pN') else 'cN' if code.startswith('cN') else 'N'
                exact={'bladder':{'N3':[7]},'utuc':{'N2':[12]},'testis':{'pN2':[14],'M1b':[16]},'penile':{'pN3':[18]}}.get(current['id'],{}).get(code,[])
                if dim=='N' and current['id'] in ('utuc','urethral'):
                    site_rows=[('proximal',L('Becken / oberer Ureter','Pelvis / proximal ureter','Pelvis / uréter proximal'),L('Hier ist der Primärtumor im Nierenbecken oder oberen Ureter; hiläre und retroperitoneale Knoten sind regional.', 'Here the primary is renal pelvic or proximal ureteric; hilar and retroperitoneal nodes are regional.', 'Aquí el primario está en pelvis o uréter proximal; ganglios hiliares y retroperitoneales son regionales.')),('distal',L('Mittlerer / distaler Ureter','Mid / distal ureter','Uréter medio / distal'),L('Beim mittleren und distalen Ureter sind auch pelvine Knoten regional. N1/N2 richten sich weiter nach Anzahl und Größe, nicht nach der Seite.', 'For mid and distal ureter, pelvic nodes are also regional. N1/N2 still depend on number and size, not laterality.', 'En uréter medio y distal también son regionales los ganglios pélvicos. N1/N2 depende de número y tamaño, no lateralidad.'))] if current['id']=='utuc' else [('posterior',L('Posteriore Urethra','Posterior urethra','Uretra posterior'),L('Die posteriore männliche Urethra drainiert in pelvine Lymphknoten; die vordere hat einen anderen ersten Abflussweg.', 'Posterior male urethra drains to pelvic nodes; the anterior segment has a different initial route.', 'La uretra masculina posterior drena a ganglios pélvicos; la anterior tiene otra vía inicial.')),('anterior',L('Anteriore Urethra','Anterior urethra','Uretra anterior'),L('Die anteriore männliche Urethra drainiert zuerst in oberflächliche und tiefe inguinale, dann in pelvine Knoten. Die Karte zeigt beide Stationen.', 'Anterior male urethra drains first to superficial and deep inguinal, then pelvic nodes. Both stations are shown.', 'La uretra masculina anterior drena primero a inguinales superficiales y profundos, luego pélvicos. Se muestran ambas estaciones.'))]
                    for i,(site,name,border) in enumerate(site_rows):stage(id+'-'+site,code,'spread',code,border,name,section=si,cases=exact if i==0 else [],dimension=dim,site=site)
                    continue
                stage(id,code,'spread',code.split(' / ')[0],L('Ordne den Befund zuerst der richtigen regionalen Station oder einem Fernmetastasenort zu. Dann gilt die organabhängige Regel daneben.', 'First identify the correct regional station or distant site, then apply the organ-specific rule alongside the map.', 'Primero identifica la estación regional o el sitio distante y después aplica la regla específica indicada.'),section=si,cases=exact,dimension=dim)

    begin('rcc','kidney')
    for v,c in [('t1a','T1a'),('t1b','T1b'),('t2a','T2a'),('t2b','T2b')]:stage(v,c,'kidney',v,L('Der Tumor bleibt auf die Niere begrenzt. Die größte Ausdehnung entscheidet innerhalb T1/T2.', 'The tumour remains confined to the kidney. Greatest dimension decides within T1/T2.', 'El tumor queda limitado al riñón. La dimensión mayor determina T1/T2.'),cases=[1] if v=='t1a' else [])
    for v,n,b in [
      ('t3a-fat',L('Fettinvasion','Fat invasion','Invasión grasa'),L('Die Nierenkapsel ist überschritten; der Tumor liegt im perirenalen Fett, aber noch innerhalb der Gerota-Faszie.', 'The renal capsule is crossed into perirenal fat, but the tumour stays within Gerota fascia.', 'Se cruza la cápsula renal hacia la grasa perirrenal, pero se permanece dentro de Gerota.')),
      ('t3a-sinus',L('Sinusfett','Sinus fat','Grasa del seno'),L('Das Nierensinusfett ist infiltriert. Das zählt auch bei einem kleinen Primärtumor als T3a.', 'Renal sinus fat is invaded. This is T3a even with a small primary.', 'La invasión de grasa del seno es T3a incluso con un primario pequeño.')),
      ('t3a-collecting',L('Kelch-Becken-System','Collecting system','Sistema colector'),L('Die Invasion erreicht das Kelch-Becken-System; hier wird ein RCC, kein Urothelkarzinom, eingestuft.', 'Invasion reaches the collecting system; this is RCC staging, not urothelial carcinoma.', 'La invasión alcanza el sistema colector; se estadifica un carcinoma renal, no urotelial.')),
      ('t3a-vein',L('Nierenvene','Renal vein','Vena renal'),L('Der Tumorthrombus liegt in der Nierenvene oder ihren segmentalen Ästen. Er erreicht die V. cava noch nicht.', 'Tumour thrombus occupies the renal vein or segmental branches, without reaching the cava.', 'El trombo ocupa la vena renal o sus ramas segmentarias sin alcanzar la cava.'))]:stage(v,'T3a','kidney',v,b,n,cases=[2] if v=='t3a-fat' else [])
    stage('t3b','T3b','kidney','t3b',L('Tumorthrombus in der V. cava unterhalb des Zwerchfells, ohne Wandinvasion.', 'Caval tumour thrombus below the diaphragm, without wall invasion.', 'Trombo en la cava por debajo del diafragma sin invasión de pared.'),cases=[3])
    stage('t3c-height','T3c','kidney','t3c-height',L('Die Thrombusspitze liegt oberhalb des Zwerchfells. Der Zwerchfellbezug verändert T3b zu T3c.', 'The thrombus tip lies above the diaphragm. This height changes T3b to T3c.', 'La punta supera el diafragma. Esta altura cambia T3b a T3c.'),L('Oberhalb des Zwerchfells','Above diaphragm','Sobre el diafragma'))
    stage('t3c-wall','T3c','kidney','t3c-wall',L('Der Tumor infiltriert die Kavawand: T3c unabhängig von der Höhe der Thrombusspitze.', 'The tumour invades the caval wall: T3c regardless of thrombus height.', 'La invasión de la pared de la cava es T3c independientemente de la altura.'),L('Kavawand','Caval wall','Pared de la cava'))
    stage('t4','T4','kidney','t4',L('Der Tumor überschreitet die Gerota-Faszie. Perirenales Fett allein bleibt dagegen T3a.', 'The tumour crosses Gerota fascia. Perirenal fat invasion alone remains T3a.', 'Se cruza la fascia de Gerota. La grasa perirrenal aislada sigue siendo T3a.'))
    stage('t4-adrenal','T4','kidney','t4-adrenal',L('Kontinuierliches Einwachsen in die ipsilaterale Nebenniere ist T4. Ein separater Nebennierenherd kann M1 sein.', 'Contiguous invasion of the ipsilateral adrenal is T4. A separate adrenal metastasis can be M1.', 'La invasión continua de la suprarrenal ipsilateral es T4; una metástasis separada puede ser M1.'),L('Direkte Nebenniereninvasion','Direct adrenal invasion','Invasión suprarrenal directa'),cases=[4]);spread_stages()

    begin('bladder','bladder')
    bounds={
      'Ta':L('Papillärer Tumor wächst in das Lumen, ohne die Basalmembran zu durchbrechen.', 'Papillary tumour grows into the lumen without crossing the basement membrane.', 'El tumor papilar crece hacia la luz sin atravesar la membrana basal.'),
      'Tis':L('Flache Läsion bleibt im Urothel. Flach bedeutet nicht biologisch harmlos.', 'A flat lesion remains in the urothelium. Flat does not mean biologically harmless.', 'La lesión plana queda en el urotelio. Plana no significa biológicamente inocua.'),
      'T1':L('Invasion in die Lamina propria, ohne Muscularis propria. Muscularis mucosae zählt nicht als T2.', 'Lamina propria invasion without muscularis propria. Muscularis mucosae does not establish T2.', 'Invasión de lámina propia sin muscular propia. La muscular de la mucosa no establece T2.'),
      'T2a':L('Die innere Hälfte der Muscularis propria ist infiltriert; die gestrichelte Linie trennt schematisch die Hälften.', 'Inner half of muscularis propria is invaded; the dashed line separates the schematic halves.', 'Se invade la mitad interna de la muscular propia; la línea discontinua separa las mitades.'),
      'T2b':L('Der Tumor erreicht die äußere Hälfte der Muscularis propria, bleibt aber innerhalb der Blasenwand.', 'Tumour reaches the outer half of muscularis propria but remains within the bladder wall.', 'El tumor alcanza la mitad externa de la muscular propia, aún dentro de la pared.'),
      'T3a':L('Einzelne Tumorzellen im perivesikalen Fett sind nur mikroskopisch erkennbar: deshalb kleine Zellnester im vergrößerten Wandschnitt.', 'Tumour cells in perivesical fat are detectable only microscopically: small nests are shown in the enlarged wall.', 'Células en grasa perivesical visibles solo al microscopio: se muestran pequeños nidos en el corte ampliado.'),
      'T3b':L('Eine makroskopisch erkennbare extravesikale Tumormasse wächst in das Fett außerhalb der Muscularis propria.', 'A grossly visible extravesical mass extends into fat beyond muscularis propria.', 'Una masa extravesical macroscópica invade la grasa más allá de la muscular propia.'),
      'T4a':L('Beispiel: direkte Invasion in das Prostatastroma (P). Auch Samenblasen, Uterus oder Vagina können T4a begründen.', 'Example: direct prostatic stromal invasion (P). Seminal vesicles, uterus or vagina can also establish T4a.', 'Ejemplo: invasión directa del estroma prostático (P). Vesículas seminales, útero o vagina también pueden establecer T4a.'),
      'T4b':L('Der Tumor infiltriert die Becken- oder Bauchwand; ein bloßer Kontakt ist keine bewiesene Invasion.', 'Tumour invades pelvic or abdominal wall; contact alone does not prove invasion.', 'Se invade la pared pélvica o abdominal; el contacto aislado no demuestra invasión.')}
    for c,b in bounds.items():stage(c.lower(),c,'bladder',c.lower(),b,cases={'T1':[5],'T3a':[6]}.get(c,[]))
    spread_stages()

    begin('prostate','prostate')
    for c,v,b in [
      ('cT1c','ct1c',L('Biopsienachweis bei nicht tastbarem Tumor. Die Zeichnung macht den Herd sichtbar; für cT1c bleibt der DRU-Befund entscheidend.', 'Biopsy-detected, nonpalpable tumour. The drawing reveals the focus; cT1c still depends on DRE.', 'Tumor de biopsia no palpable. El dibujo revela el foco; cT1c sigue dependiendo del tacto rectal.')),
      ('cT2a','ct2a',L('Tastbarer, organbegrenzter Befund: höchstens die Hälfte eines Lappens. Das Bild ersetzt die DRU nicht.', 'Palpable, confined disease involving no more than half of one lobe. The drawing does not replace DRE.', 'Enfermedad palpable y confinada hasta la mitad de un lóbulo. El dibujo no sustituye el tacto.')),
      ('cT2b','ct2b',L('Tastbarer Befund in mehr als der Hälfte eines Lappens, ohne Befall beider Lappen.', 'Palpable involvement of more than half of one lobe, without both lobes involved.', 'Afectación palpable de más de la mitad de un lóbulo, sin afectar ambos.')),
      ('cT2c','ct2c',L('Beide Lappen sind klinisch befallen. Diese Unterteilung gilt nicht für pT2 nach Prostatektomie.', 'Both lobes are clinically involved. This subdivision does not apply to pT2 after prostatectomy.', 'Ambos lóbulos afectados clínicamente. Esta subdivisión no se aplica a pT2 tras prostatectomía.'))]:stage(c.lower(),c,'prostate',v,b,cases=[8] if c=='cT1c' else [],dimension='cT')
    stage('pt2','pT2','prostate','pt2',L('Nach OP bleibt der Tumor organbegrenzt, auch bei beidseitigem Befall. pT2 hat keine a/b/c-Untergruppen.', 'After surgery the tumour is confined, even if bilateral. pT2 has no a/b/c subdivisions.', 'Tras cirugía el tumor permanece confinado aunque sea bilateral. pT2 no tiene subgrupos a/b/c.'),cases=[9],dimension='pT')
    for c,v,b,n in [
      ('pT3a','t3a',L('Tumor überschreitet die Prostatagrenze in das extraprostatische Gewebe. Ein positiver Schnittrand allein definiert R1, nicht T3a.', 'Tumour crosses the prostate boundary into extraprostatic tissue. A positive margin alone establishes R1, not T3a.', 'El tumor cruza el límite prostático hacia tejido externo. Un margen positivo aislado es R1, no T3a.'),L('Extraprostatisches Wachstum','Extraprostatic','Extraprostático')),
      ('pT3a','t3a-neck',L('Mikroskopische Blasenhalsinvasion zählt als pT3a. Sie ist nicht automatisch eine ausgedehnte Blaseninvasion mit T4.', 'Microscopic bladder neck invasion is pT3a, not automatically extensive bladder invasion with T4.', 'La invasión microscópica del cuello vesical es pT3a, no automáticamente invasión extensa T4.'),L('Mikroskopischer Blasenhals','Microscopic bladder neck','Cuello vesical microscópico')),
      ('pT3b','t3b',L('Der Tumor wächst in die Samenblase. Nähe oder Kontakt allein reichen für die Einstufung nicht.', 'Tumour invades the seminal vesicle. Proximity or contact alone is insufficient.', 'El tumor invade la vesícula seminal. La proximidad o el contacto no bastan.'),L('Samenblase','Seminal vesicle','Vesícula seminal')),
      ('pT4','t4',L('Beispiel: direkte Rektuminvasion. Andere Nachbarstrukturen außer den Samenblasen können ebenfalls T4 begründen.', 'Example: direct rectal invasion. Other adjacent structures apart from seminal vesicles can also establish T4.', 'Ejemplo: invasión directa del recto. Otras estructuras vecinas salvo vesículas seminales también pueden establecer T4.'),L('Nachbarorgan','Adjacent organ','Órgano vecino'))]:stage('p-'+v,c,'prostate',v,b,n,cases=[10] if v=='t3a-neck' else [],dimension='pT')
    # cT3/4: the same anatomic extent, but a separate clinical assessment.
    for c,v in [('cT3a','t3a'),('cT3b','t3b'),('cT4','t4')]:stage(c.lower(),c,'prostate',v,L('Klinische Kategorie separat von der pathologischen Kategorie berichten; in der EAU-Risikostratifizierung basiert cT auf der DRU.', 'Report the clinical category separately from pathology; EAU risk stratification bases cT on DRE.', 'Informa la categoría clínica separada de la patológica; la estratificación EAU basa cT en tacto rectal.'),dimension='cT')
    spread_stages()

    begin('utuc','ureter')
    for c,v,b in [('Ta','ta',L('Papillär, ohne Invasion in das subepitheliale Gewebe.', 'Papillary, without subepithelial invasion.', 'Papilar, sin invasión subepitelial.')),('Tis','tis',L('Flache intraepitheliale Läsion ohne Stromainvasion.', 'Flat intraepithelial lesion without stromal invasion.', 'Lesión plana intraepitelial sin invasión estromal.')),('T1','t1',L('Basalmembran überschritten, Muskelschicht noch frei.', 'Basement membrane crossed; muscle remains uninvolved.', 'Se cruza la membrana basal; el músculo permanece libre.')),('T2','t2',L('Invasion in die Muskelschicht des Ureters oder Nierenbeckens.', 'Invasion of ureteric or renal pelvic muscle.', 'Invasión del músculo ureteral o de la pelvis renal.'))]:stage(v,c,'ureter',v,b)
    stage('t3-pelvis','T3','kidney','utuc-t3',L('Nierenbecken-UC wächst in das Nierenparenchym oder peripelvine Fett. Das dargestellte Organ ist keine RCC-Stagingregel.', 'Renal pelvic UC invades renal parenchyma or peripelvic fat. This is not an RCC staging rule.', 'El UC de pelvis invade parénquima renal o grasa peripélvica. No se aplica la regla del carcinoma renal.'),L('Nierenbecken → Parenchym','Renal pelvis → parenchyma','Pelvis → parénquima'),row='T3 – Nierenbecken',cases=[11])
    stage('t3-ureter','T3','ureter','t3',L('Ureter-UC überschreitet die Muskelschicht in das periureterale Fett.', 'Ureteric UC crosses muscle into periureteric fat.', 'El UC ureteral cruza el músculo hacia grasa periureteral.'),L('Ureter → Fett','Ureter → fat','Uréter → grasa'),row='T3 – Ureter')
    stage('t4','T4','kidney','utuc-t4',L('Nierenbecken-UC wächst durch die Niere in das perirenale Fett: T4. Beim RCC kann perirenale Fettinvasion noch T3a sein.', 'Renal pelvic UC crosses the kidney into perirenal fat: T4. In RCC, perirenal fat invasion can still be T3a.', 'UC de pelvis atraviesa el riñón hasta grasa perirrenal: T4. En carcinoma renal esa grasa puede ser T3a.'));spread_stages()

    begin('testis','testis')
    for id,c,v,b,n in [
      ('t1','pT1','t1',L('Tumor im Hoden ohne lymphovaskuläre Invasion und ohne Vaginalisbefall. Der histologische Befund ergänzt die Anatomie.', 'Tumour within the testis without lymphovascular invasion or vaginalis involvement. Histology complements anatomy.', 'Tumor en el testículo sin invasión linfovascular ni vaginal. La histología complementa la anatomía.'),L('Hodenbegrenzt','Confined to testis','Confinado al testículo')),
      ('t2-lvi','pT2','t2-lvi',L('Tumorzellen in einem Lymph- oder Blutgefäß sind LVI. Der vergrößerte Gefäßausschnitt zeigt, warum trotz kleinem Tumor pT2 möglich ist.', 'Tumour cells inside a lymphatic or blood vessel establish LVI. The vessel inset shows why a small primary can be pT2.', 'Células en vaso linfático o sanguíneo establecen invasión linfovascular. El detalle explica pT2 con un primario pequeño.'),L('Lymphovaskuläre Invasion','Lymphovascular invasion','Invasión linfovascular')),
      ('t2-vaginalis','pT2','t2-vaginalis',L('Tumor wächst durch die Albuginea in die Vaginalis. Vaginalis ist nicht die Skrotalwand; diese wäre pT4.', 'Tumour crosses albuginea into vaginalis. Vaginalis is not scrotal wall; scrotal invasion is pT4.', 'Se cruza albugínea hacia vaginal. Vaginal no es pared escrotal; invadirla sería pT4.'),L('Vaginalisbefall','Vaginalis involvement','Afectación vaginal')),
      ('t3','pT3','t3',L('Der Samenstrang ist infiltriert. LVI allein im Hoden ist bereits pT2, aber nicht gleich Samenstranginvasion.', 'The spermatic cord is invaded. LVI alone in the testis is pT2, not cord invasion.', 'Se invade el cordón. La invasión linfovascular aislada del testículo es pT2, no invasión del cordón.'),L('Samenstrang','Spermatic cord','Cordón')),
      ('t4','pT4','t4',L('Der Tumor erreicht die Skrotalwand, außerhalb der testikulären Hüllen.', 'Tumour reaches scrotal wall outside the testicular coverings.', 'El tumor alcanza la pared escrotal fuera de las cubiertas testiculares.'),L('Skrotalwand','Scrotal wall','Pared escrotal'))]:stage(id,c,'testis',v,b,n,cases=[13] if id=='t2-vaginalis' else [],dimension='pT')
    spread_stages()
    for c in ('S1','S2','S3'):stage(c.lower(),c,'markers',c,L('Die höchste Kategorie eines der drei Marker entscheidet. Ein einzelner Wert an der S2-Grenze genügt für S2; S0 ist separat zu beurteilen.', 'The highest category of any marker decides. One value at an S2 threshold is enough for S2; assess S0 separately.', 'Decide la categoría más alta de cualquier marcador. Un valor en el umbral S2 basta para S2; S0 se valora aparte.'),cases=[15] if c=='S2' else [],dimension='S')

    begin('penile','penis')
    for c,v,b in [('T1a','t1a',L('Subepitheliales Gewebe, ohne LVI/PNI und ohne schlechte Differenzierung. Diese Risikomerkmale sind histologisch, nicht am Umriss erkennbar.', 'Subepithelial tissue without LVI/PNI or poor differentiation. These risks are histological, not visible from outline alone.', 'Tejido subepitelial sin invasión linfovascular/perineural ni mala diferenciación. Los riesgos son histológicos.')),('T1b','t1b',L('Gleiche anatomische Tiefe wie T1a; LVI, PNI oder schlechte Differenzierung verändern die Untergruppe. Das Detail zeigt LVI als ein Beispiel.', 'Same depth as T1a; LVI, PNI or poor differentiation changes the subgroup. The inset illustrates LVI as one example.', 'Misma profundidad que T1a; invasión linfovascular/perineural o mala diferenciación cambia el subgrupo. El detalle ejemplifica invasión vascular.')),('T2','t2',L('Corpus spongiosum infiltriert, mit oder ohne Urethrabefall. Die Urethra liegt im Spongiosum: sie allein macht keinen T3-Tumor.', 'Corpus spongiosum invaded, with or without urethral involvement. The urethra lies within spongiosum and does not alone establish T3.', 'Se invade el esponjoso con o sin uretra. La uretra está dentro del esponjoso y por sí sola no establece T3.')),('T3','t3',L('Ein oder beide Corpora cavernosa sind infiltriert. Der axiale Schnitt zeigt die dorsalen Schwellkörper getrennt vom ventralen Spongiosum.', 'One or both cavernosa are invaded. The axial view separates dorsal cavernosa from ventral spongiosum.', 'Se invade uno o ambos cavernosos. El corte axial separa cavernosos dorsales del esponjoso ventral.')),('T4','t4',L('Ausbreitung über den Penis hinaus in weitere Nachbarstrukturen; der rote Fortsatz zeigt schematisch die externe Invasion.', 'Spread beyond the penis into other adjacent structures; the red extension schematically indicates external invasion.', 'Extensión fuera del pene a otras estructuras vecinas; la prolongación roja indica invasión externa esquemática.'))]:stage(v,c,'penis',v,b,cases=[17] if c=='T2' else [])
    spread_stages()

    begin('urethral','urethra')
    for c,v,b in [('T1','t1',L('Invasion in subepitheliales Bindegewebe. Die organabhängigen Sonderregeln für Divertikel und prostatisches UC bleiben wichtig.', 'Subepithelial invasion. Special rules for diverticula and prostatic UC remain important.', 'Invasión subepitelial. Importan las reglas de divertículos y UC prostático.')),('T2','t2',L('Im männlichen Beispiel: Spongiosuminvasion. Prostata oder periurethrale Muskulatur sind weitere T2-Strukturen.', 'Male example: spongiosum invasion. Prostate or periurethral muscle are other T2 structures.', 'Ejemplo masculino: invasión del esponjoso. Próstata o músculo periuretral son otras estructuras T2.')),('T3','t3',L('Im Beispiel: Cavernosuminvasion. Auch jenseits der Prostatakapsel, vordere Vaginalwand oder Blasenhals gehören zu T3.', 'Example: cavernosum invasion. Beyond prostate capsule, anterior vaginal wall or bladder neck are also T3.', 'Ejemplo: invasión del cavernoso. Fuera de cápsula prostática, pared vaginal anterior o cuello vesical también son T3.')),('T4','t4',L('Invasion weiterer Nachbarorgane, zum Beispiel Blase außerhalb des Blasenhalses.', 'Invasion of other adjacent organs, for example bladder beyond its neck.', 'Invasión de otros órganos vecinos, por ejemplo vejiga fuera del cuello.'))]:stage(v,c,'urethra',v,b)
    stage('tis-pu','Tis pu','prostate','tis-pu',L('Carcinoma in situ bleibt in der prostatischen Urethraschleimhaut.', 'Carcinoma in situ remains in prostatic urethral mucosa.', 'Carcinoma in situ limitado a mucosa uretral prostática.'),dimension='UC')
    stage('tis-pd','Tis pd','prostate','tis-pd',L('CIS besiedelt Prostatagänge, ohne Invasion in das Prostatastroma. Gangbefall ist nicht automatisch T2.', 'CIS colonises prostatic ducts without stromal invasion. Duct involvement is not automatically T2.', 'El CIS afecta conductos sin invasión estromal. La afectación ductal no es automáticamente T2.'),cases=[19],dimension='UC');spread_stages()

    begin('acc','adrenal')
    for c,v,b in [('T1','acc-t1',L('Auf die Nebenniere begrenzt und höchstens 5 cm. Bei genau 5 cm bleibt ACC T1.', 'Confined to adrenal and at most 5 cm. ACC at exactly 5 cm remains T1.', 'Confinado y hasta 5 cm. Exactamente 5 cm sigue siendo T1 en ACC.')),('T2','acc-t2',L('Auf die Nebenniere begrenzt, aber größer als 5 cm. Invasion hat Vorrang vor der Größenregel.', 'Confined but greater than 5 cm. Invasion takes precedence over size.', 'Confinado pero mayor de 5 cm. La invasión prima sobre el tamaño.')),('T3','acc-t3',L('Invasion in periadrenales Gewebe, ohne Invasion eines Nachbarorgans.', 'Periadrenal tissue invasion without adjacent organ invasion.', 'Invasión de tejido perisuprarrenal sin invadir un órgano vecino.')),('T4','acc-t4',L('Invasion eines großen Gefäßes, etwa V. cava oder Nierenvene. T4 N0 M0 ist Stadium III; Stadium IV erfordert M1.', 'Major vessel invasion, such as cava or renal vein. T4 N0 M0 is stage III; stage IV requires M1.', 'Invasión de vaso mayor como cava o vena renal. T4 N0 M0 es estadio III; IV exige M1.'))]:stage(v,c,'adrenal',v,b,cases=[20] if c=='T4' else [])
    stage('t4-kidney','T4','adrenal','acc-t4-kidney',L('Direkte Niereninvasion ist ein zweiter Weg zu T4. T4 allein ist keine Fernmetastase.', 'Direct kidney invasion is another route to T4. T4 alone is not distant metastasis.', 'La invasión directa del riñón es otra vía a T4. T4 aislado no es metástasis distante.'),L('Direkte Niereninvasion','Direct renal invasion','Invasión renal directa'));spread_stages()

    begin('ppgl','adrenal')
    for c,v,b,n in [('T1','ppgl-t1',L('Phäochromozytom kleiner als 5 cm, ohne extraadrenale Invasion.', 'Pheochromocytoma below 5 cm, without extra-adrenal invasion.', 'Feocromocitoma menor de 5 cm sin invasión extraadrenal.'),L('Phäochromozytom <5 cm','Pheochromocytoma <5 cm','Feocromocitoma <5 cm')),('T2','ppgl-t2',L('Phäochromozytom mindestens 5 cm, noch ohne Invasion. Genau 5 cm unterscheidet PPGL von der ACC-Größenregel.', 'Pheochromocytoma at least 5 cm without invasion. Exactly 5 cm differs from the ACC size rule.', 'Feocromocitoma de al menos 5 cm sin invasión. Exactamente 5 cm difiere de la regla ACC.'),L('Phäochromozytom ≥5 cm','Pheochromocytoma ≥5 cm','Feocromocitoma ≥5 cm')),('T2','pgl-t2',L('Sympathisches Paragangliom jeder Größe ohne Invasion: T2. Parasympathische Kopf-Hals-Paragangliome gehören nicht in dieses Schema.', 'Sympathetic paraganglioma of any size without invasion: T2. Parasympathetic head and neck PGL are outside this scheme.', 'Paraganglioma simpático de cualquier tamaño sin invasión: T2. Los parasimpáticos de cabeza y cuello quedan fuera.'),L('Sympathisches PGL','Sympathetic PGL','PGL simpático')),('T3','ppgl-t3',L('Invasion in umgebende Strukturen, einschließlich großer Gefäße. Dieses PPGL-Schema hat keine T4-Kategorie.', 'Invasion of surrounding structures including major vessels. This PPGL scheme has no T4 category.', 'Invasión de estructuras vecinas incluidos vasos mayores. Este esquema PPGL no tiene T4.'),L('Invasion','Invasion','Invasión'))]:stage(v,c,'adrenal',v,b,n,cases=[21] if v=='pgl-t2' else [])
    spread_stages()

    begin('trauma-kidney','kidney')
    for c,v,b in [('I','renal-i',L('Kontusion oder subkapsuläres Hämatom ohne Parenchymlazeration.', 'Contusion or subcapsular haematoma without parenchymal laceration.', 'Contusión o hematoma subcapsular sin laceración parenquimatosa.')),('II','renal-ii',L('Parenchymriss unter 1 cm Tiefe, ohne Urinleck. Ein nicht expandierendes perirenales Hämatom ist ein weiterer II-Befund.', 'Parenchymal tear below 1 cm, without urine leak. Nonexpanding perirenal haematoma is another grade II finding.', 'Rotura de menos de 1 cm sin fuga urinaria. Hematoma perirrenal no expansivo es otro hallazgo II.')),('III','renal-iii',L('Riss tiefer als 1 cm, aber kein Eintritt in das Sammelsystem. Gefäßbefunde werden separat beurteilt.', 'Tear deeper than 1 cm without collecting-system entry. Assess vascular findings separately.', 'Rotura mayor de 1 cm sin alcanzar sistema colector. Los hallazgos vasculares se evalúan aparte.')),('IV','renal-iv-leak',L('Der Riss erreicht das Kelch-Becken-System. Blaue Tropfen zeigen extravasierenden Urin; die Spätphase kann das Leck nachweisen.', 'The tear reaches the collecting system. Blue drops show urine extravasation; delayed imaging may reveal the leak.', 'La rotura alcanza el sistema colector. Las gotas azules indican orina extravasada; la fase tardía puede demostrarla.')),('IV','renal-iv-infarct',L('Eine devaskularisierte Niere durch Thrombose ohne aktive Blutung kann nach AAST 2018 Grad IV sein. Grau zeigt fehlende Perfusion.', 'Devascularisation by thrombosis without active bleeding can be grade IV in AAST 2018. Grey indicates absent perfusion.', 'Desvascularización por trombosis sin sangrado activo puede ser IV en AAST 2018. Gris indica ausencia de perfusión.')),('V','renal-v',L('Beispiel: zertrümmerte Niere. Kreislaufstabilität und Blutung bestimmen das Vorgehen; die Zahl allein bedeutet keine automatische Nephrektomie.', 'Example: shattered kidney. Haemodynamic stability and bleeding guide treatment; the grade alone does not mandate nephrectomy.', 'Ejemplo: riñón destrozado. Estabilidad y sangrado guían tratamiento; el grado solo no impone nefrectomía.'))]:stage(v,c,'kidney',v,b,cases={'renal-ii':[22],'renal-iv-leak':[23],'renal-iv-infarct':[24]}.get(v,[]),dimension='injury')

    begin('trauma-ureter','ureter')
    for c,v,b in [('I','i',L('Kontusion ohne Durchtrennung. Eine Wandkontusion kann trotzdem später zu Ischämie oder Stenose führen.', 'Contusion without transection. Wall contusion can still cause later ischaemia or stricture.', 'Contusión sin sección. Puede causar después isquemia o estenosis.')),('II','ii',L('Weniger als die Hälfte des Ureterumfangs ist eingerissen, die Kontinuität bleibt erhalten.', 'Less than half the circumference is torn; continuity remains.', 'Se desgarra menos de la mitad de la circunferencia; persiste continuidad.')),('III','iii',L('Mehr als die Hälfte des Umfangs ist eingerissen, aber keine komplette Durchtrennung.', 'More than half the circumference is torn, without complete transection.', 'Se desgarra más de la mitad sin sección completa.')),('IV','iv',L('Komplette Durchtrennung mit weniger als 2 cm devaskularisiertem Abschnitt. Die Lücke ist schematisch, nicht die Messung am OP-Präparat.', 'Complete transection with less than 2 cm devascularisation. The gap is schematic, not a specimen measurement.', 'Sección completa con menos de 2 cm desvascularizados. La separación es esquemática, no una medición quirúrgica.')),('V','v',L('Avulsion mit mehr als 2 cm Devaskularisation. Blutversorgung der verbleibenden Enden gehört zur Rekonstruktionsplanung.', 'Avulsion with more than 2 cm devascularisation. Viability of remaining ends matters for reconstruction.', 'Avulsión con más de 2 cm desvascularizados. La viabilidad de extremos importa para reconstrucción.'))]:stage(v,c,'ureter',v,b,cases=[25] if c=='III' else [],dimension='injury')

    begin('trauma-bladder','bladder-trauma')
    stage('contusion','I','bladder-trauma','i',L('Kontusion oder partielle Wandlazeration, ohne vollständige Wandruptur. Eine Zystographie beurteilt bei entsprechender Klinik ein mögliches Leck.', 'Contusion or partial wall laceration without full-thickness rupture. Cystography assesses possible leakage when indicated.', 'Contusión o lesión parcial sin rotura de espesor completo. La cistografía evalúa fuga cuando está indicada.'),dimension='injury')
    for id,c,v,b,n in [('ep-small','II','ep',L('Extraperitonealer Riss unter 2 cm. Urin tritt seitlich in den extraperitonealen Raum aus; der Peritonealbezug ist wichtiger als die Zahl allein.', 'Extraperitoneal tear below 2 cm. Urine leaks laterally into extraperitoneal space; the peritoneal relationship matters beyond the grade.', 'Rotura extraperitoneal menor de 2 cm. Fuga lateral extraperitoneal; la relación peritoneal importa además del grado.'),L('Extraperitoneal <2 cm','Extraperitoneal <2 cm','Extraperitoneal <2 cm')),('ep-large','III','ep',L('Extraperitonealer Riss über 2 cm. Komplikationen wie Knochenfragmente oder Blasenhalsbeteiligung können eine Reparatur erfordern.', 'Extraperitoneal tear over 2 cm. Bone fragments or neck involvement can require repair.', 'Rotura extraperitoneal mayor de 2 cm. Fragmentos óseos o afectación del cuello pueden requerir reparación.'),L('Extraperitoneal >2 cm','Extraperitoneal >2 cm','Extraperitoneal >2 cm')),('ip-small','III','ip',L('Intraperitonealer Riss unter 2 cm an der Kuppel. Bei stumpfem Trauma ist trotz kleiner Läsion eine operative Reparatur erforderlich.', 'Intraperitoneal dome tear below 2 cm. Blunt intraperitoneal rupture requires repair despite small size.', 'Rotura intraperitoneal de cúpula menor de 2 cm. En trauma cerrado requiere reparación aunque sea pequeña.'),L('Intraperitoneal <2 cm','Intraperitoneal <2 cm','Intraperitoneal <2 cm')),('ip-large','IV','ip',L('Intraperitonealer Riss über 2 cm. Aktive retrograde Zystographie, nicht bloß gefüllte Blase in der Ausscheidungsphase, prüft die Ruptur.', 'Intraperitoneal tear over 2 cm. Active retrograde cystography, not passive excretory filling alone, evaluates rupture.', 'Rotura intraperitoneal mayor de 2 cm. Se evalúa con cistografía retrógrada activa, no solo llenado excretor.'),L('Intraperitoneal >2 cm','Intraperitoneal >2 cm','Intraperitoneal >2 cm')),('neck','V','neck',L('Blasenhals, Trigonum oder Uretermündung sind betroffen. Diese Lage macht die Verletzung komplex und beeinflusst die Reparatur.', 'Neck, trigone or ureteric orifice is involved. This location makes injury complex and affects repair.', 'Cuello, trígono u orificio ureteral afectados. Esta localización hace compleja la lesión y condiciona reparación.'),L('Blasenhals / Trigonum','Neck / trigone','Cuello / trígono'))]:stage(id,c,'bladder-trauma',id if id!='neck' else v,b,n,cases=[26] if id=='ip-large' else [27] if id=='ep-large' else [],dimension='injury')

    begin('trauma-urethra','urethra')
    for c,v,b in [('Anterior','anterior',L('Bulbäre oder penile Urethra. Blut am Meatus nach Reitunfall führt zur gezielten Urethrabeurteilung, nicht zu wiederholtem blindem Katheterisieren.', 'Bulbar or penile urethra. Blood at the meatus after straddle injury prompts targeted assessment, not repeated blind catheterisation.', 'Uretra bulbar o peneana. Sangre en meato tras lesión a horcajadas requiere evaluación dirigida, no sondajes ciegos repetidos.')),('Posterior / PFUI','posterior',L('Prostatisch oder membranös, häufig mit Beckenringverletzung. Die Lage des Beckenbruchs ersetzt keine Prüfung der Urethrakontinuität.', 'Prostatic or membranous, often with pelvic ring injury. Fracture location does not replace assessment of urethral continuity.', 'Prostática o membranosa, a menudo con lesión pélvica. La fractura no sustituye valorar continuidad uretral.')),('Partial','partial',L('Restkontinuität ist erhalten. Extravasation allein kann die Unterscheidung partiell versus komplett nicht sicher leisten; Endoskopie kann ergänzen.', 'Some continuity remains. Extravasation alone may not reliably distinguish partial from complete injury; endoscopy may help.', 'Persiste continuidad parcial. Extravasación sola puede no distinguir parcial de completa; endoscopia puede ayudar.')),('Complete','complete',L('Vollständige Unterbrechung. Das Schema zeigt die anatomische Definition, nicht den Beweis durch ein einzelnes RUG-Merkmal.', 'Complete disruption. The diagram shows the anatomic definition, not proof from a single RUG feature.', 'Interrupción completa. El dibujo muestra la definición anatómica, no prueba por un único signo de uretrografía.'))]:stage(v,c,'urethra',v,b,cases=[28] if c=='Partial' else [],dimension='injury')

    begin('trauma-genital','testis')
    for c,v,b in [('III','testis-iii',L('Albuginealazeration mit weniger als 50 % Parenchymverlust. Der dunkle Sektor zeigt schematisch verlorenes Gewebe; vitales Gewebe soll erhalten werden.', 'Albuginea laceration with less than 50% tissue loss. The dark sector schematically shows lost tissue; preserve viable tissue.', 'Laceración de albugínea con pérdida menor del 50%. El sector oscuro indica pérdida esquemática; se preserva tejido viable.')),('IV','testis-iv',L('Mehr als 50 % Parenchymverlust. Der dunkle Anteil ist ein Lernschema, keine Methode zur Volumenmessung.', 'More than 50% tissue loss. The dark region is a teaching diagram, not a volumetric measurement.', 'Pérdida mayor del 50%. El sector oscuro es didáctico, no una medición volumétrica.')),('V','testis-v',L('Vollständige Zerstörung oder Avulsion des Hodens; der tatsächliche Vitalitätsbefund entscheidet über Erhaltbarkeit.', 'Complete destruction or avulsion; actual tissue viability determines salvageability.', 'Destrucción completa o avulsión; la viabilidad real determina si se puede conservar.'))]:stage(v,c,'testis',v,b,cases=[29] if c=='III' else [],dimension='injury')
    stage('penile-fracture','Penisfraktur','penis','fracture',L('Die kavernöse Tunica albuginea reißt. Zeitnahe operative Reparatur und Beurteilung einer begleitenden Urethraläsion gehören zusammen.', 'Cavernosal tunica albuginea tears. Prompt repair and assessment of associated urethral injury belong together.', 'Rotura de albugínea cavernosa. Se combinan reparación pronta y valoración de lesión uretral asociada.'),cases=[30],dimension='injury')
    data['illustrationsVersion']=1
    file.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')

    # Upgrade the atlas drawings too. Existing part ids and question links stay valid.
    file=ROOT/'data/schemas.json'; schemas=json.loads(file.read_text())
    models={'tnm-rcc':'kidney','tnm-bladder':'bladder','tnm-prostate':'prostate','tnm-testis':'testis'}
    for s in schemas:
        if s['id'] not in models:continue
        model=models[s['id']];fn,labs=MODELS[model];allowed={p['id'] for p in s['parts']}
        svg=fn();svg=re.sub(r' data-part="([^"]+)"',lambda m:m[0] if m[1] in allowed else '',svg)
        svg=re.sub(r'<text\b[^>]*data-label="([^"]+)"[^>]*>.*?</text>',lambda m:m[0] if m[1] in allowed else '',svg)
        s['svg']='<g transform="scale(0.625)">'+svg+'</g>'
        s['labels']=[l for l in labels(labs) if l['id'] in allowed]
        s['caption']=ORIENT[model]

    by_schema={s['id']:s for s in schemas}
    s=by_schema['tnm-urogenital'];source=by_schema['urinary-tract-overview']['svg']
    remap={'adrenal-glands':'adrenal','right-kidney':'kidney','left-kidney':'kidney','renal-pelvis':'kidney','ureters':'ureter','narrowing-puj':'ureter','narrowing-iliac':'ureter','narrowing-vuj':'ureter','bladder':'bladder','urethra':'urethra'}
    source=re.sub(r' data-part="([^"]+)"',lambda m:' data-part="'+remap[m[1]]+'"' if m[1] in remap else '',source)
    source+=a.group('sympathetic',a.ellipse(327,148,7,13,'#d4b392','#8c7083',2)+a.path('M327 161V181',stroke='#c3a394',width=4))
    s['svg']=source
    s['caption']=L('Frontalübersicht des Harntrakts mit Nieren, Nebennieren und sympathischem Paraganglion. Die TNM-Lektionen zeigen zusätzlich organbezogene Schnittbilder.', 'Frontal urinary tract overview with kidneys, adrenals and a sympathetic paraganglion. TNM lessons additionally provide organ-specific sections.', 'Vista frontal del tracto urinario con riñones, suprarrenales y un paraganglio simpático. Las lecciones TNM añaden cortes de cada órgano.')
    s=by_schema['trauma-kidney-map'];svg=a.kidney()
    remap={'kidney':'parenchyma','renal-medulla':'parenchyma','capsule':'parenchyma','collecting-system':'collecting','renal-vein':'vessels','renal-artery':'vessels'}
    svg=re.sub(r' data-part="([^"]+)"',lambda m:' data-part="'+remap[m[1]]+'"' if m[1] in remap else '',svg)
    svg=re.sub(r'<text\b[^>]*>.*?</text>','',svg)
    svg+=a.group('upj',a.path('M438 350Q459 356 467 378',stroke='#70587b',width=4))
    s['svg']='<g transform="scale(0.625)">'+svg+'</g>';s['caption']=ORIENT['kidney']
    s=by_schema['trauma-bladder-map'];s['svg']='<g transform="scale(0.625)">'+a.bladder_trauma().replace(' data-part="finding"','')+'</g>';s['caption']=ORIENT['bladder-trauma']
    s['labels']=labels(a.BLADDER_TRAUMA_LABELS)
    file.write_text(json.dumps(schemas,ensure_ascii=False,indent=2)+'\n',newline='\r\n')
    print('Illustrated guides:',len(guides),'· stage-specific lessons:',sum(len(g['visual']['stages']) for g in guides.values()))


